import { tags } from "typia";

/**
 * Count result for active reactions on a comment. This DTO is a computed
 * response and does not directly map to a Prisma model. It aggregates
 * civic_board_comment_reactions respecting comment/post visibility
 * (civic_board_comments.status and parent civic_board_posts.status). No
 * personal data is included.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICivicBoardCommentReactionCount = {
  /**
   * UUID of the target comment whose reactions are being counted. Matches
   * civic_board_comments.id. Included for clarity in read responses; source
   * is the path parameter.
   */
  civic_board_comment_id: string & tags.Format<"uuid">;

  /**
   * Total number of active reactions (single-like toggles) for the target
   * comment. This is computed by counting rows in
   * civic_board_comment_reactions where civic_board_comment_id equals the
   * requested comment and deleted_at IS NULL. When reactions are globally
   * disabled or disallowed on comments by civic_board_reaction_policies,
   * providers should return 0 while still succeeding.
   */
  count: number & tags.Type<"int32"> & tags.Minimum<0>;
};
